use genex::prelude::*;

/// The one predicate the HUD draws by and the ads demo reports.
pub fn crosshair_visible(w: &super::World) -> bool { w.aim < 0.5 }

pub fn wire(game: &mut Game<super::World>) {
    game.on_ui(|sim, ui, _ctx| {
        if !crosshair_visible(&sim.world) { return; } // hidden down the sights, never beside them
        draw_crosshair(ui);
    });
    game.demo("ads", |d| {
        d.sim_mut().world.aim_held = true;
        d.advance_ms(400);
        json!({ "crosshairVisible": crosshair_visible(&d.sim().world) })
    });
}

fn draw_crosshair(ui: &mut egui::Ui) { ui.label("+"); }
